macro_rules! deps {
    () => {
        SeekResult!();
        ReadError!();
        InfoType!();
        WriteError!();
        Error!();
        Socket!();
    };
}

macro_rules! Handler {
    () => {
        deps!();
        # [doc = " A trait for the various callbacks used by libcurl to invoke user code."] # [doc = ""] # [doc = " This trait represents all operations that libcurl can possibly invoke a"] # [doc = " client for code during an HTTP transaction. Each callback has a default"] # [doc = " \"noop\" implementation, the same as in libcurl. Types implementing this trait"] # [doc = " may simply override the relevant functions to learn about the callbacks"] # [doc = " they're interested in."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use curl::easy::{Easy2, Handler, WriteError};"] # [doc = ""] # [doc = " struct Collector(Vec<u8>);"] # [doc = ""] # [doc = " impl Handler for Collector {"] # [doc = "     fn write(&mut self, data: &[u8]) -> Result<usize, WriteError> {"] # [doc = "         self.0.extend_from_slice(data);"] # [doc = "         Ok(data.len())"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " let mut easy = Easy2::new(Collector(Vec::new()));"] # [doc = " easy.get(true).unwrap();"] # [doc = " easy.url(\"https://rust-lang.org/\").unwrap();"] # [doc = " easy.perform().unwrap();"] # [doc = ""] # [doc = " assert_eq!(easy.response_code().unwrap(), 200);"] # [doc = " let contents = easy.get_ref();"] # [doc = " println!(\"{}\", String::from_utf8_lossy(&contents.0));"] # [doc = " ```"] pub trait Handler { # [doc = " Callback invoked whenever curl has downloaded data for the application."] # [doc = ""] # [doc = " This callback function gets called by libcurl as soon as there is data"] # [doc = " received that needs to be saved."] # [doc = ""] # [doc = " The callback function will be passed as much data as possible in all"] # [doc = " invokes, but you must not make any assumptions. It may be one byte, it"] # [doc = " may be thousands. If `show_header` is enabled, which makes header data"] # [doc = " get passed to the write callback, you can get up to"] # [doc = " `CURL_MAX_HTTP_HEADER` bytes of header data passed into it.  This"] # [doc = " usually means 100K."] # [doc = ""] # [doc = " This function may be called with zero bytes data if the transferred file"] # [doc = " is empty."] # [doc = ""] # [doc = " The callback should return the number of bytes actually taken care of."] # [doc = " If that amount differs from the amount passed to your callback function,"] # [doc = " it'll signal an error condition to the library. This will cause the"] # [doc = " transfer to get aborted and the libcurl function used will return"] # [doc = " an error with `is_write_error`."] # [doc = ""] # [doc = " If your callback function returns `Err(WriteError::Pause)` it will cause"] # [doc = " this transfer to become paused. See `unpause_write` for further details."] # [doc = ""] # [doc = " By default data is sent into the void, and this corresponds to the"] # [doc = " `CURLOPT_WRITEFUNCTION` and `CURLOPT_WRITEDATA` options."] fn write (& mut self , data : & [u8]) -> Result < usize , WriteError > { Ok (data . len ()) } # [doc = " Read callback for data uploads."] # [doc = ""] # [doc = " This callback function gets called by libcurl as soon as it needs to"] # [doc = " read data in order to send it to the peer - like if you ask it to upload"] # [doc = " or post data to the server."] # [doc = ""] # [doc = " Your function must then return the actual number of bytes that it stored"] # [doc = " in that memory area. Returning 0 will signal end-of-file to the library"] # [doc = " and cause it to stop the current transfer."] # [doc = ""] # [doc = " If you stop the current transfer by returning 0 \"pre-maturely\" (i.e"] # [doc = " before the server expected it, like when you've said you will upload N"] # [doc = " bytes and you upload less than N bytes), you may experience that the"] # [doc = " server \"hangs\" waiting for the rest of the data that won't come."] # [doc = ""] # [doc = " The read callback may return `Err(ReadError::Abort)` to stop the"] # [doc = " current operation immediately, resulting in a `is_aborted_by_callback`"] # [doc = " error code from the transfer."] # [doc = ""] # [doc = " The callback can return `Err(ReadError::Pause)` to cause reading from"] # [doc = " this connection to pause. See `unpause_read` for further details."] # [doc = ""] # [doc = " By default data not input, and this corresponds to the"] # [doc = " `CURLOPT_READFUNCTION` and `CURLOPT_READDATA` options."] # [doc = ""] # [doc = " Note that the lifetime bound on this function is `'static`, but that"] # [doc = " is often too restrictive. To use stack data consider calling the"] # [doc = " `transfer` method and then using `read_function` to configure a"] # [doc = " callback that can reference stack-local data."] fn read (& mut self , data : & mut [u8]) -> Result < usize , ReadError > { let _ = data ; Ok (0) } # [doc = " User callback for seeking in input stream."] # [doc = ""] # [doc = " This function gets called by libcurl to seek to a certain position in"] # [doc = " the input stream and can be used to fast forward a file in a resumed"] # [doc = " upload (instead of reading all uploaded bytes with the normal read"] # [doc = " function/callback). It is also called to rewind a stream when data has"] # [doc = " already been sent to the server and needs to be sent again. This may"] # [doc = " happen when doing a HTTP PUT or POST with a multi-pass authentication"] # [doc = " method, or when an existing HTTP connection is reused too late and the"] # [doc = " server closes the connection."] # [doc = ""] # [doc = " The callback function must return `SeekResult::Ok` on success,"] # [doc = " `SeekResult::Fail` to cause the upload operation to fail or"] # [doc = " `SeekResult::CantSeek` to indicate that while the seek failed, libcurl"] # [doc = " is free to work around the problem if possible. The latter can sometimes"] # [doc = " be done by instead reading from the input or similar."] # [doc = ""] # [doc = " By default data this option is not set, and this corresponds to the"] # [doc = " `CURLOPT_SEEKFUNCTION` and `CURLOPT_SEEKDATA` options."] fn seek (& mut self , whence : SeekFrom) -> SeekResult { let _ = whence ; SeekResult :: CantSeek } # [doc = " Specify a debug callback"] # [doc = ""] # [doc = " `debug_function` replaces the standard debug function used when"] # [doc = " `verbose` is in effect. This callback receives debug information,"] # [doc = " as specified in the type argument."] # [doc = ""] # [doc = " By default this option is not set and corresponds to the"] # [doc = " `CURLOPT_DEBUGFUNCTION` and `CURLOPT_DEBUGDATA` options."] fn debug (& mut self , kind : InfoType , data : & [u8]) { debug (kind , data) } # [doc = " Callback that receives header data"] # [doc = ""] # [doc = " This function gets called by libcurl as soon as it has received header"] # [doc = " data. The header callback will be called once for each header and only"] # [doc = " complete header lines are passed on to the callback. Parsing headers is"] # [doc = " very easy using this. If this callback returns `false` it'll signal an"] # [doc = " error to the library. This will cause the transfer to get aborted and"] # [doc = " the libcurl function in progress will return `is_write_error`."] # [doc = ""] # [doc = " A complete HTTP header that is passed to this function can be up to"] # [doc = " CURL_MAX_HTTP_HEADER (100K) bytes."] # [doc = ""] # [doc = " It's important to note that the callback will be invoked for the headers"] # [doc = " of all responses received after initiating a request and not just the"] # [doc = " final response. This includes all responses which occur during"] # [doc = " authentication negotiation. If you need to operate on only the headers"] # [doc = " from the final response, you will need to collect headers in the"] # [doc = " callback yourself and use HTTP status lines, for example, to delimit"] # [doc = " response boundaries."] # [doc = ""] # [doc = " When a server sends a chunked encoded transfer, it may contain a"] # [doc = " trailer. That trailer is identical to a HTTP header and if such a"] # [doc = " trailer is received it is passed to the application using this callback"] # [doc = " as well. There are several ways to detect it being a trailer and not an"] # [doc = " ordinary header: 1) it comes after the response-body. 2) it comes after"] # [doc = " the final header line (CR LF) 3) a Trailer: header among the regular"] # [doc = " response-headers mention what header(s) to expect in the trailer."] # [doc = ""] # [doc = " For non-HTTP protocols like FTP, POP3, IMAP and SMTP this function will"] # [doc = " get called with the server responses to the commands that libcurl sends."] # [doc = ""] # [doc = " By default this option is not set and corresponds to the"] # [doc = " `CURLOPT_HEADERFUNCTION` and `CURLOPT_HEADERDATA` options."] fn header (& mut self , data : & [u8]) -> bool { let _ = data ; true } # [doc = " Callback to progress meter function"] # [doc = ""] # [doc = " This function gets called by libcurl instead of its internal equivalent"] # [doc = " with a frequent interval. While data is being transferred it will be"] # [doc = " called very frequently, and during slow periods like when nothing is"] # [doc = " being transferred it can slow down to about one call per second."] # [doc = ""] # [doc = " The callback gets told how much data libcurl will transfer and has"] # [doc = " transferred, in number of bytes. The first argument is the total number"] # [doc = " of bytes libcurl expects to download in this transfer. The second"] # [doc = " argument is the number of bytes downloaded so far. The third argument is"] # [doc = " the total number of bytes libcurl expects to upload in this transfer."] # [doc = " The fourth argument is the number of bytes uploaded so far."] # [doc = ""] # [doc = " Unknown/unused argument values passed to the callback will be set to"] # [doc = " zero (like if you only download data, the upload size will remain 0)."] # [doc = " Many times the callback will be called one or more times first, before"] # [doc = " it knows the data sizes so a program must be made to handle that."] # [doc = ""] # [doc = " Returning `false` from this callback will cause libcurl to abort the"] # [doc = " transfer and return `is_aborted_by_callback`."] # [doc = ""] # [doc = " If you transfer data with the multi interface, this function will not be"] # [doc = " called during periods of idleness unless you call the appropriate"] # [doc = " libcurl function that performs transfers."] # [doc = ""] # [doc = " `progress` must be set to `true` to make this function actually get"] # [doc = " called."] # [doc = ""] # [doc = " By default this function calls an internal method and corresponds to"] # [doc = " `CURLOPT_PROGRESSFUNCTION` and `CURLOPT_PROGRESSDATA`."] fn progress (& mut self , dltotal : f64 , dlnow : f64 , ultotal : f64 , ulnow : f64) -> bool { let _ = (dltotal , dlnow , ultotal , ulnow) ; true } # [doc = " Callback to SSL context"] # [doc = ""] # [doc = " This callback function gets called by libcurl just before the"] # [doc = " initialization of an SSL connection after having processed all"] # [doc = " other SSL related options to give a last chance to an"] # [doc = " application to modify the behaviour of the SSL"] # [doc = " initialization. The `ssl_ctx` parameter is actually a pointer"] # [doc = " to the SSL library's SSL_CTX. If an error is returned from the"] # [doc = " callback no attempt to establish a connection is made and the"] # [doc = " perform operation will return the callback's error code."] # [doc = ""] # [doc = " This function will get called on all new connections made to a"] # [doc = " server, during the SSL negotiation. The SSL_CTX pointer will"] # [doc = " be a new one every time."] # [doc = ""] # [doc = " To use this properly, a non-trivial amount of knowledge of"] # [doc = " your SSL library is necessary. For example, you can use this"] # [doc = " function to call library-specific callbacks to add additional"] # [doc = " validation code for certificates, and even to change the"] # [doc = " actual URI of a HTTPS request."] # [doc = ""] # [doc = " By default this function calls an internal method and"] # [doc = " corresponds to `CURLOPT_SSL_CTX_FUNCTION` and"] # [doc = " `CURLOPT_SSL_CTX_DATA`."] # [doc = ""] # [doc = " Note that this callback is not guaranteed to be called, not all versions"] # [doc = " of libcurl support calling this callback."] fn ssl_ctx (& mut self , cx : * mut c_void) -> Result < () , Error > { ssl_ctx (cx) } # [doc = " Callback to open sockets for libcurl."] # [doc = ""] # [doc = " This callback function gets called by libcurl instead of the socket(2)"] # [doc = " call. The callback function should return the newly created socket"] # [doc = " or `None` in case no connection could be established or another"] # [doc = " error was detected. Any additional `setsockopt(2)` calls can of course"] # [doc = " be done on the socket at the user's discretion. A `None` return"] # [doc = " value from the callback function will signal an unrecoverable error to"] # [doc = " libcurl and it will return `is_couldnt_connect` from the function that"] # [doc = " triggered this callback."] # [doc = ""] # [doc = " By default this function opens a standard socket and"] # [doc = " corresponds to `CURLOPT_OPENSOCKETFUNCTION `."] fn open_socket (& mut self , family : c_int , socktype : c_int , protocol : c_int ,) -> Option < curl_sys :: curl_socket_t > { return Socket :: new (family . into () , socktype . into () , Some (protocol . into ())) . ok () . map (cvt) ; # [cfg (unix)] fn cvt (socket : Socket) -> curl_sys :: curl_socket_t { use std :: os :: unix :: prelude :: * ; socket . into_raw_fd () } # [cfg (windows)] fn cvt (socket : Socket) -> curl_sys :: curl_socket_t { use std :: os :: windows :: prelude :: * ; socket . into_raw_socket () } } }
    };
}

Handler!()